  1712
  1713      /* Axis normalization is a two-stage process.  First we normalize */
  1714      /* based on the [min,def,max] values for the axis to be [-1,0,1]. */
  1715      /* Then, if there's an `avar' table, we renormalize this range.   */
  1716
  1717      FT_TRACE5(( "design coordinates:\n" ));
  1718
  1719      a = mmvar->axis;
  1720      for ( i = 0; i < num_coords; i++, a++ )
  1721      {
  1722        FT_Fixed  coord = coords[i];
  1723
  1724
  1725        FT_TRACE5(( "  %.5f\n", coord / 65536.0 ));
  1726        if ( coord > a->maximum || coord < a->minimum )
  1727        {
  1728          FT_TRACE1((
  1729            "ft_var_to_normalized: design coordinate %.5f\n"
  1730            "                      is out of range [%.5f;%.5f]; clamping\n",
  1731            coord / 65536.0,
  1732            a->minimum / 65536.0,
  1733            a->maximum / 65536.0 ));
  1734
  1735          if ( coord > a->maximum)
  1736            coord = a->maximum;
  1737          else
  1738            coord = a->minimum;
  1739        }
  1740
  1741        if ( coord < a->def )
  1742          normalized[i] = -FT_DivFix( coords[i] - a->def,
  1743                                      a->minimum - a->def );
  1744        else if ( coord > a->def )
  1745          normalized[i] = FT_DivFix( coords[i] - a->def,
  1746                                     a->maximum - a->def );
  1747        else
  1748          normalized[i] = 0;
  1749      }
  1750
  1751      FT_TRACE5(( "\n" ));
  1752
  1753      for ( ; i < mmvar->num_axis; i++ )
  1754        normalized[i] = 0;
  1755
  1756      if ( blend->avar_segment )
  1757      {
  1758        FT_TRACE5(( "normalized design coordinates"
  1759                    " before applying `avar' data:\n" ));
  1760
  1761        av = blend->avar_segment;
  1762        for ( i = 0; i < mmvar->num_axis; i++, av++ )
  1763        {
  1764          for ( j = 1; j < (FT_UInt)av->pairCount; j++ )
  1765          {
  1766            if ( normalized[i] < av->correspondence[j].fromCoord )
  1767            {
  1768              FT_TRACE5(( "  %.5f\n", normalized[i] / 65536.0 ));
  1769
  1770              normalized[i] =
  1771                FT_MulDiv( normalized[i] - av->correspondence[j - 1].fromCoord,
  1772                           av->correspondence[j].toCoord -
  1773                             av->correspondence[j - 1].toCoord,
  1774                           av->correspondence[j].fromCoord -
  1775                             av->correspondence[j - 1].fromCoord ) +
  1776                av->correspondence[j - 1].toCoord;
  1777              break;
  1778            }
  1779          }
  1780        }
  1781      }
  1782    }
